I.append(R(6295599,"दाल और टर्की भरी शिमला मिर्च","ये भरी हुई शिमला मिर्चें एक संतुलित भोजन हैं, जिनमें दाल और टर्की का प्रोटीन सब्ज़ियों और मसालों के जीवंत स्वादों के साथ मिलता है। यह एक संतोषजनक और मधुमेह के अनुकूल रात के खाने का विकल्प है।","8","1 भरी हुई शिमला मिर्च का आधा भाग",
["1 कप दाल (सूखी, धोई और छनी हुई)","2 कप कम सोडियम वाला सब्ज़ी का शोरबा","4 बड़ी शिमला मिर्च","1 पाउंड कम चर्बी वाला टर्की का कीमा (93% लीन)","1 छोटा प्याज़","2 कली लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच सूखा अजवायन (ओरेगानो)","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","1 (14 औंस) डिब्बा कटे हुए डिब्बाबंद टमाटर (बिना नमक मिलाए, छने हुए)","1/2 कप आंशिक रूप से मलाई निकाला हुआ मोज़ेरेला (कद्दूकस किया हुआ)","1 बड़ा चम्मच ताज़ा अजमोद (पार्सली)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें।","एक मध्यम सॉसपैन में दाल और सब्ज़ी का शोरबा मिलाएँ। उबाल आने दें, फिर आँच कम करें और लगभग 20–25 मिनट तक या दाल के नरम होने तक धीमी आँच पर पकाएँ। अतिरिक्त तरल छान दें।","जब दाल पक रही हो, तब आधी कटी शिमला मिर्चों को बेकिंग डिश में रखें। फ़ॉइल से ढकें और नरम होने तक 30 मिनट बेक करें।","एक बड़े तवे या कड़ाही में मध्यम आँच पर कटा हुआ प्याज़ डालें और नरम होने तक 5 मिनट भूनें। कड़ाही में लहसुन डालें, फिर टर्की का कीमा डालें। भूरा होने और बस पकने तक पकाएँ।","इसमें पिसा जीरा, स्मोक्ड पेपरिका, सूखा अजवायन, कोशर नमक और काली मिर्च मिलाएँ।","कड़ाही में पकी हुई दाल, कटे हुए टमाटर और 1/2 कप कद्दूकस किया हुआ मोज़ेरेला डालें। अच्छी तरह मिलने तक चलाएँ।","दाल और टर्की का मिश्रण हर नरम की हुई शिमला मिर्च के आधे भाग में चम्मच से भरें।","हर भरी हुई शिमला मिर्च के ऊपर बचा हुआ कद्दूकस किया मोज़ेरेला डालें।","बेकिंग डिश को एल्युमिनियम फ़ॉइल से ढकें और 20–25 मिनट तक या शिमला मिर्च पूरी तरह पकने तक बेक करें।","फ़ॉइल हटाएँ और पनीर के पिघलकर बुलबुले उठने तक अतिरिक्त 3–5 मिनट ब्रॉयल करें। चाहें तो ताज़ा अजमोद से सजाएँ।"]))
I.append(R(6297358,"बेक किए हुए सेब","बेक किए हुए सेब पतझड़ में बनाने के लिए एक स्वादिष्ट मिठाई हैं। सेब की प्राकृतिक मिठास का उपयोग करते हुए, यह रेसिपी मधुमेह के अनुकूल मिठाई बन सकती है।","4","1/2 कप",
["2 बड़े सेब (बीज निकालकर कटे हुए)","2 बड़े चम्मच शुगर-फ़्री बहु-उपयोगी सिरप","1/2 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसा जायफल"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। 9x9 इंच की बेकिंग डिश पर बेकिंग पेपर लगाएँ।","सेब के टुकड़ों को तैयार की गई बेकिंग डिश में रखें, ऊपर से सिरप डालें और दालचीनी व जायफल छिड़कें।","सेबों पर बराबर लेप लगाने के लिए मिलाएँ।","सेब के नरम होने तक 25 से 30 मिनट बेक करें। गरमागरम परोसें।"]))
I.append(R(6298457,"बादाम के आटे के पैनकेक","ये ग्लूटेन-फ़्री बादाम के आटे के पैनकेक अपनी सुबह को आनंददायक बनाएँ, जो आपको ऊर्जावान रखने के लिए पर्याप्त प्रोटीन देते हैं।","4","2 पैनकेक",
["2/3 कप बादाम का आटा","2/3 कप ग्लूटेन-फ़्री आटा","1 1/2 छोटा चम्मच बेकिंग पाउडर","1/8 छोटा चम्मच कोशर नमक","2/3 कप अंडे का विकल्प","2/3 कप बिना चीनी का बादाम दूध","1 बड़ा चम्मच कैनोला तेल","1 बड़ा चम्मच शुगर-फ़्री मेपल-प्रकार का सिरप","1 1/2 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1 स्प्रे नॉनस्टिक कुकिंग स्प्रे","4 मध्यम ताज़ी स्ट्रॉबेरी (कटी हुई, सजाने के लिए)"],
["एक कटोरे में बादाम का आटा, ग्लूटेन-फ़्री आटा, बेकिंग पाउडर और नमक को फेंटकर मिलाएँ।","एक अलग कटोरे में अंडे के विकल्प को फेंटें और उसमें बादाम दूध, कैनोला तेल, शुगर-फ़्री मेपल सिरप और वनीला एक्स्ट्रैक्ट डालें। अच्छी तरह मिलाएँ।","गीली सामग्री को सूखी सामग्री में डालें और मिलने तक चलाएँ। घोल को गाढ़ा होने के लिए कुछ मिनट रखा रहने दें।","तवा या ग्रिडल को मध्यम आँच पर गरम करें और कुकिंग स्प्रे से चिकना करें।","हर पैनकेक के लिए तवे पर ¼ कप घोल डालें। चम्मच के पिछले भाग से घोल को हल्का सा फैलाएँ।","सतह पर बुलबुले बनने तक पकाएँ, फिर पलटें और दूसरी तरफ़ सुनहरा भूरा होने तक पकाएँ।","बचे हुए घोल के साथ यही दोहराएँ।","ऊपर से एक ताज़ी कटी स्ट्रॉबेरी रखकर परोसें।"]))
I.append(R(6299047,"कैलिफ़ोर्निया खजूर और एवोकाडो चॉकलेट पुडिंग","यह मखमली पुडिंग एक पोषक तत्वों से भरपूर विशेष व्यंजन है, जो पके एवोकाडो और प्राकृतिक रूप से मीठे खजूर जैसी संपूर्ण खाद्य सामग्री से बना है, इसमें अलग से चीनी मिलाने की ज़रूरत नहीं है। फ़ाइबर का उत्कृष्ट स्रोत और हृदय के लिए लाभकारी वसा से भरपूर, यह पारंपरिक चॉकलेट पुडिंग का एक बेहतर विकल्प है। सबसे अच्छी बात यह है कि यह सिर्फ़ 10 मिनट में तैयार हो जाती है!","2","1/2 कप",
["4 पूरे कैलिफ़ोर्निया खजूर (गुठली निकालकर कटे हुए)","1 पूरा एवोकाडो (कैलिफ़ोर्निया, गुठली निकाला हुआ)","1/4 कप बिना चीनी का बादाम दूध","2 1/2 बड़े चम्मच + 1/16 छोटा चम्मच (बाँटकर) बिना चीनी का कोको पाउडर","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1/4 छोटा चम्मच पिसी दालचीनी","1/8 छोटा चम्मच बारीक समुद्री नमक","6 पूरी ताज़ी रसभरी (ऊपर सजाने के लिए)"],
["खजूर को नरम करने के लिए 5 मिनट तक गुनगुने पानी में भिगोएँ, फिर छान लें। व्यंजन को सजाने के लिए कुछ छोटे टुकड़े अलग रख दें।","फ़ूड प्रोसेसर या हाई-स्पीड ब्लेंडर में बचे हुए खजूर, एवोकाडो, बादाम दूध, 2 ½ बड़े चम्मच कोको पाउडर, वनीला, दालचीनी और समुद्री नमक डालें। पूरी तरह चिकना और मलाईदार होने तक ब्लेंड करें, ज़रूरत हो तो बीच में किनारों से मिश्रण को खुरच लें।","2 छोटे कटोरों या जार में चम्मच से डालें और ऊपर रसभरी रखें। अलग रखे हुए कटे खजूर और कोको पाउडर से सजाएँ। पुडिंग का तुरंत आनंद लें, या गाढ़ी, मूस जैसी बनावट के लिए परोसने से पहले 30 मिनट फ़्रिज में रखें।"]))
I.append(R(6299118,"केला नारियल स्मूदी","इस मधुमेह के अनुकूल केला नारियल स्मूदी के साथ उष्णकटिबंधीय इलाके की सैर करें! इसके स्वाद ऐसे घुल-मिल जाते हैं कि इस पौष्टिक और स्वादिष्ट पेय का आनंद लेते हुए आपको लगेगा कि आप समुद्र तट पर हैं।","2","8 औंस",
["1 छोटा केला","1/4 कप नारियल का दूध (बिना चीनी का)","1/4 कप पानी","1/4 कप सादा बिना चर्बी वाला ग्रीक योगर्ट","1/2 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1/2 कप बर्फ़ के टुकड़े","1/2 छोटा चम्मच पिसी दालचीनी (सजाने के लिए, वैकल्पिक)"],
["केला, नारियल का दूध, योगर्ट, कद्दूकस किया नारियल, वनीला एक्स्ट्रैक्ट और बर्फ़ को ब्लेंडर में डालें। चिकना और मलाईदार होने तक ब्लेंड करें।","चाहें तो दालचीनी से सजाएँ। तुरंत आनंद लें।"]))
I.append(R(6301257,"कुरकुरा चिकन फ़्राइड “राइस”","अगर आपका मन सब्ज़ियों से भरपूर तीखा व्यंजन खाने का है, तो यह आपके लिए ही है। सब्ज़ियों और कुरकुरे चिकन टेंडर्स से भरपूर, यह बेहतरीन स्वाद वाला कम कार्बोहाइड्रेट और प्रोटीन से भरपूर व्यंजन है।","2","4 औंस चिकन + 1 – ¼ कप सब्ज़ियाँ",
["2 बड़े चम्मच कैनोला तेल","1/4 किलो चिकन टेंडर्स","1/4 कप प्याज़ (छोटे टुकड़ों में कटा हुआ)","1/4 कप गाजर (कटी हुई)","1/4 कप लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","1/2 कप जमी हुई ब्रोकोली के फूल","1/4 कप पतली कटी हुई स्नो पीज़","1 कप फूलगोभी का “राइस”","1/4 कप अंडे का विकल्प","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1 छोटा चम्मच तिल का तेल (टोस्ट किया हुआ)","1 छोटा चम्मच बारीक कटी ताज़ी अदरक","1/2 छोटा चम्मच लाल मिर्च के फ़्लेक्स","2 डंठल हरी प्याज़ (कटी हुई)"],
["एक बड़ी कड़ाही में कैनोला तेल को मध्यम-तेज़ आँच पर गरम करें। चिकन टेंडर्स डालें और भूरे और कुरकुरे होने तक 5 मिनट पकाएँ। उन्हें पलटें और 5 मिनट और पकाएँ। उन्हें कड़ाही से निकालकर प्लेट में रखें और गरम रखने के लिए फ़ॉइल से ढक दें।","कड़ाही में प्याज़, लहसुन, गाजर और शिमला मिर्च डालें। लगातार चलाते हुए 3 मिनट पकाएँ। ब्रोकोली, स्नो पीज़ और फूलगोभी डालें। ब्रोकोली के चटक हरे रंग की होने तक लगातार चलाते हुए 2–3 मिनट और पकाएँ। अंडे का विकल्प डालें और उसे भुर्जी की तरह पकाएँ।","एक छोटे कटोरे में सोया सॉस, तिल का तेल, अदरक और मिर्च के फ़्लेक्स मिलाएँ। इस मिश्रण को सब्ज़ियों में डालें और उन पर लपेटने के लिए चलाएँ।","चिकन को वापस सब्ज़ियों के बीच रखें और तब तक धीमी आँच पर पकाएँ जब तक चिकन का आंतरिक तापमान 165 डिग्री F तक न पहुँच जाए।","कटी हुई हरी प्याज़ से सजाकर परोसें।"]))
I.append(R(6305434,"बीफ़ और फूलगोभी राइस स्टिर फ़्राई","एशियाई शैली की घर पर बनी सॉस की हल्की तीखेपन के साथ, यह बीफ़ और फूलगोभी राइस स्टिर फ़्राई हफ़्ते के दिनों के रात के खाने के लिए एक स्वादिष्ट भोजन है। मधुमेह के अनुकूल और ताज़ी सब्ज़ियों से भरपूर, यह एक सेहतमंद विकल्प है जिसका पूरा परिवार आनंद ले सकता है।","4","1 कप स्टिर फ़्राई + 1/2 कप फूलगोभी राइस",
["1/2 छोटा चम्मच बेकिंग सोडा","3 1/2 बड़े चम्मच पानी (बाँटकर)","1 पाउंड सर्लोइन स्टेक (दिखने वाली चर्बी हटाई हुई, 15 मिनट फ़्रीज़र में रखी हुई, 3 इंच के पतले टुकड़ों में कटी हुई)","1 1/2 बड़े चम्मच कोकोनट एमिनोज़ (सोया सॉस का विकल्प)","2 बड़े चम्मच हॉइसिन सॉस","2 कली लहसुन (बारीक कटा हुआ)","1 1/2 छोटा चम्मच ताज़ी अदरक (कटी हुई)","1/2 छोटा चम्मच कुटी हुई लाल मिर्च के फ़्लेक्स","1 बड़ा चम्मच ग्रेपसीड तेल (या कोई अन्य बिना स्वाद वाला तेल)","2 मध्यम गाजर (पतले गोल टुकड़ों में कटी हुई)","1 गुच्छा ब्रोकोली (छोटे फूलों में कटी हुई, लगभग 3 कप)","3 कप पत्तागोभी (लाल या हरी, पतली कटी हुई)","1 मध्यम लाल शिमला मिर्च (पतली कटी हुई)","4 डंठल हरी प्याज़ (पतली कटी हुई, बाँटकर)","2 कप जमी हुई फूलगोभी राइस (भाप में पकी हुई, परोसने के लिए)"],
["मैरिनेड के लिए, एक कटोरे में बेकिंग सोडा को 2 बड़े चम्मच पानी के साथ फेंटें। बीफ़ पर इस मिश्रण को लगाएँ और फ़्रिज में 5–30 मिनट रखा रहने दें।","सॉस बनाने के लिए, एक छोटे कटोरे में कोकोनट एमिनोज़, हॉइसिन सॉस, 1 ½ बड़े चम्मच पानी, लहसुन, अदरक और कुटी लाल मिर्च के फ़्लेक्स को मिलाएँ।","एक बड़ी कड़ाही या वोक में तेल को मध्यम-तेज़ आँच पर गरम करें। बीफ़ डालें और बाहर से कुरकुरा लेकिन अंदर से अभी गुलाबी रहने तक, लगभग 2–3 मिनट पकाएँ। 1 बड़ा चम्मच सॉस डालकर 30 सेकंड पकाएँ। छेदवाले चम्मच से बीफ़ को प्लेट में निकाल लें।","वोक में गाजर, ब्रोकोली, पत्तागोभी और शिमला मिर्च डालें, और हल्का कुरकुरा-नरम होने तक, लगभग 6 मिनट पकाएँ।","आँच को मध्यम करें, बीफ़ को वापस वोक में डालें और बची हुई सॉस ऊपर से डालें। आधी हरी प्याज़ डालें। 1 मिनट पकाएँ।","भाप में पकी फूलगोभी राइस को प्लेटों में बाँट लें, ऊपर बीफ़ और ब्रोकोली रखें और सारी सॉस शामिल करना सुनिश्चित करें। बची हुई हरी प्याज़ से सजाएँ।"]))
I.append(R(6306338,"तरबूज़ गाज़पाचो","इस ताज़गी भरे तरबूज़ गाज़पाचो के साथ गर्मियों की तपिश से राहत पाएँ! गाज़पाचो एक ठंडा सूप है जिसे पकाने की ज़रूरत नहीं होती और जिसमें ताज़ी, ब्लेंड की हुई सब्ज़ियाँ इस्तेमाल होती हैं। इसलिए यह गर्मियों की एक बेहतरीन रेसिपी है जिसे आप अपनी अगली BBQ पार्टी में परोस सकते हैं।","6","1 & 1/2 कप",
["4 कप बीज रहित तरबूज़ (चौकोर टुकड़ों में कटा हुआ)","1 खीरा (छिला और बीज निकाला हुआ)","1/2 लाल शिमला मिर्च (कटी हुई)","4 मध्यम टमाटर (डंठल निकाले हुए, बीज और झिल्ली हटाई हुई)","1/2 शैलट (कटा हुआ)","1 छोटी जलापेनो मिर्च (डंठल हटाई और बीज निकाली हुई)","1 बड़ा चम्मच शेरी सिरका","1/4 कप जैतून का तेल","1/2 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च","1/4 कप ताज़ी तुलसी (पतली कतरी हुई)"],
["तरबूज़, खीरा, शिमला मिर्च, टमाटर, शैलट, जलापेनो, सिरका, जैतून का तेल, नमक और काली मिर्च को ब्लेंडर में डालें। पूरी तरह चिकना होने तक ब्लेंड करें। चखें और ज़रूरत हो तो मसाले ठीक करें।","परोसने से पहले गाज़पाचो को कम से कम एक घंटे फ़्रिज में रखें।","परोसने के लिए, गाज़पाचो को कटोरों में बाँटें और ऊपर तुलसी डालें। चाहें तो थोड़ा सा जैतून का तेल ऊपर से डालें।"]))
I.append(R(6306662,"साइडर और मेपल ग्लेज़ वाला डेलिकाटा स्क्वैश","साइडर और मेपल ग्लेज़ वाले डेलिकाटा स्क्वैश के पतझड़ से प्रेरित स्वाद का आनंद लें। यह मौसमी व्यंजन न केवल पतझड़ के सार को समेटता है, बल्कि आपके मधुमेह भोजन योजना में स्वादिष्ट पोषक तत्व भी जोड़ता है।","6","1/2 कप",
["1/4 कप सेब का साइडर","2 बड़े चम्मच मेपल सिरप","1 बड़ा चम्मच जैतून का तेल","1/2 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसा जायफल","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 पूरे डेलिकाटा स्क्वैश (आधे कटे, बीज निकाले और अर्धचंद्राकार टुकड़ों में कटे हुए)","2 बड़े चम्मच ताज़ा अजमोद (कटा हुआ, सजाने के लिए)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","एक कटोरे में सेब का साइडर, मेपल सिरप, जैतून का तेल, पिसी दालचीनी, पिसा जायफल, नमक और काली मिर्च को फेंटकर मिलाएँ।","डेलिकाटा स्क्वैश के अर्धचंद्राकार टुकड़ों को बेकिंग शीट पर एक परत में रखें।","साइडर और मेपल का मिश्रण स्क्वैश पर डालें, यह सुनिश्चित करते हुए कि वे अच्छी तरह लिपट जाएँ।","पहले से गरम किए ओवन में 25 मिनट या स्क्वैश के नरम होने तक भूनें, और बीच में एक बार पलटें।"]))
I.append(R(6306893,"बेरी सालसा","यह बेरी सालसा ताज़ा, रंगीन और प्राकृतिक मिठास से भरपूर है। बेरियों का मिश्रण चटक स्वाद देता है, जबकि मसाले और ताज़ा नींबू का रस मीठे और खट्टे का अच्छा संतुलन लाते हैं। इसे बनाना आसान है और यह ग्रिल किए व्यंजनों के साथ या हल्की, ताज़गी भरी टॉपिंग के रूप में अच्छा लगता है।","5","1/4 कप",
["1/4 छोटा चम्मच लाल मिर्च पाउडर","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक","1 बड़ा चम्मच ताज़ा नींबू का रस","1/4 कप ताज़ा धनिया पत्ती (बारीक कटी हुई)","1/4 कप लाल प्याज़ (छोटे टुकड़ों में कटा हुआ)","1/4 मध्यम एवोकाडो (छोटे टुकड़ों में कटा हुआ)","1/2 कप जमी हुई स्ट्रॉबेरी (पिघलाकर छानी हुई)","1/2 कप जमे हुए ब्लूबेरी (बिना चीनी मिलाए, पिघलाकर छाने हुए)"],
["सभी सामग्री को एक छोटे कटोरे में मिलाएँ और तुरंत परोसें, या स्वाद घुलने-मिलने के लिए परोसने से पहले फ़्रिज में 30 मिनट ठंडा करें।"]))
I.append(R(6309151,"शहद और दरदरी सरसों वाला चिकन","यह सरल और स्वादिष्ट शहद-सरसों चिकन आज़माएँ, जो परिवार को पसंद आएगा। संपूर्ण भोजन के लिए इसे किसी साबुत अनाज और बिना स्टार्च वाली सब्ज़ी के साथ परोसें।","6","लगभग 1/2 चिकन ब्रेस्ट",
["1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच डिजॉन-शैली की सरसों","2 बड़े चम्मच दरदरी डिजॉन सरसों","1 बड़ा चम्मच शहद","1 बड़ा चम्मच नींबू का रस","2 पाउंड चिकन ब्रेस्ट (बिना हड्डी, बिना त्वचा, अच्छी तरह साफ़ किए हुए)"],
["मैरिनेड की सभी सामग्री को एक मध्यम कटोरे में मिलाएँ और एक बड़े, कसकर बंद होने वाले प्लास्टिक बैग में डालें। चिकन ब्रेस्ट को कम से कम 30 मिनट, या सर्वोत्तम परिणाम के लिए रात भर फ़्रिज में मैरिनेट करें।","ग्रिल को मध्यम-तेज़ आँच पर पहले से गरम करें और चिकन को ग्रिल की जाली पर रखें। सीधी आँच पर (ग्रिल का ढक्कन बंद करके) हर तरफ़ 8-10 मिनट तक, या 165 डिग्री F का आंतरिक तापमान आने तक पकाएँ।"]))
I.append(R(6309831,"छोटा केला","केले की पोषण संबंधी जानकारी","1","छोटा केला",["1 छोटा केला"],[]))
I.append(R(6310729,"मेरा पसंदीदा सब्ज़ी का सूप","सूप बनाना आपके फ़्रिज या अलमारियों में रखी कुछ सब्ज़ियों का उपयोग करने और कुछ पैसे बचाने का एक बढ़िया तरीका है। यह सूप जैसा है वैसे ही बहुत अच्छा है, लेकिन आप कुछ सामग्री को फ़्रिज में रखी उन अन्य चीज़ों से भी बदल सकते हैं जिनका उपयोग करना ज़रूरी हो।","14","1 कप",
["1/2 पाउंड ग्राउंड चक (बीफ़ का कीमा)","7 कप टमाटर (छिले, कटे हुए)","4 कप पानी","1 (14.5 औंस) डिब्बा कटी हुई हरी फलियाँ (बिना नमक मिलाए, छनी और धुली हुई)","1 (15 औंस) डिब्बा मटर (बिना नमक मिलाए, छने और धुले हुए)","1 (15 औंस) डिब्बा मक्का (बिना नमक मिलाए, छना और धुला हुआ)","2 मध्यम गाजर (छिली और कटी हुई)","1 डंठल अजवाइन (सेलरी) (कटा हुआ)","3 मध्यम आलू (हर एक 5 औंस का, छिले और छोटे टुकड़ों में कटे हुए)","1 मध्यम प्याज़ (छोटे टुकड़ों में कटा हुआ)","1/4 कप सूखे चावल","1/8 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच कुटी लाल मिर्च के फ़्लेक्स","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच लहसुन पाउडर"],
["ग्राउंड चक को 2-गैलन के स्टॉकपॉट में रखें और मध्यम आँच पर भूरा करें। मांस निकालें और अच्छी तरह छान लें। बर्तन से चिकनाई पोंछ दें।","मांस को वापस स्टॉकपॉट में डालें, फिर टमाटर और पानी डालें। उबाल आने दें और ढककर तब तक पकाएँ जब तक टमाटर नरम न हो जाएँ और रसदार शोरबा न बन जाए, लगभग 20 मिनट।","बाकी सामग्री डालें, ढक दें और स्वाद घुलने-मिलने के लिए 60 मिनट और पकाते रहें।"]))
I.append(R(6311044,"एकोर्न स्क्वैश के साथ वन-पॉट रोस्टेड चिकन","इस स्वादिष्ट वन-पॉट मुख्य व्यंजन में मौजूद सेब और दालचीनी आपके घर को पतझड़ की स्वादिष्ट महक से भर देंगे।","4","1 चिकन थाई + 2 एकोर्न स्क्वैश की फाँकें + लगभग 4 सेब के टुकड़े",
["4 बिना हड्डी और बिना त्वचा वाली चिकन थाई (हर एक 4 औंस की)","1 छोटा चम्मच सूखा रोज़मेरी","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 छोटा चम्मच कैनोला तेल","1 मध्यम एकोर्न स्क्वैश (1-1/4 पाउंड)","1 मध्यम ग्रैनी स्मिथ या कोई अन्य खट्टा सेब (बीज निकालकर कटा हुआ)","1 बड़ा चम्मच शहद","1/4 छोटा चम्मच पिसी दालचीनी","1/2 कप पानी"],
["ओवन को 375 डिग्री F पर पहले से गरम करें।","चिकन पर रोज़मेरी लगाएँ। डच ओवन या ओवन में रखने योग्य बर्तन पर कुकिंग स्प्रे करें और तेल डालें। मध्यम-तेज़ आँच पर गरम करें। चिकन को बर्तन में रखें और हर तरफ़ 3 मिनट सेकें।","एकोर्न स्क्वैश को लंबाई में आधा काटें और बीज निकाल दें। हर आधे हिस्से को चार भागों में काटें; सिरे फेंक दें।","एकोर्न स्क्वैश और सेब के टुकड़ों को चिकन के चारों ओर रखें। स्क्वैश और सेब के टुकड़ों पर शहद बराबर मात्रा में डालें और फिर उन पर दालचीनी छिड़कें। चिकन पर पानी डालें।","ओवन में बिना ढके 45 मिनट बेक करें। परोसने के लिए, कुछ रस चिकन, स्क्वैश और सेब के ऊपर डालें।"]))
